import pytest
from candidate import sum_to_n

def test_sum_to_n_positive_number():
    assert sum_to_n(5) == 15

def test_sum_to_n_zero():
    assert sum_to_n(0) == 0

def test_sum_to_n_negative_number_returns_zero():
    assert sum_to_n(-1) == 0
    assert sum_to_n(-10) == 0

def test_sum_to_n_large_number():
    n = 10000
    expected = n * (n + 1) // 2
    assert sum_to_n(n) == expected

def test_sum_to_n_result_type_is_int():
    assert isinstance(sum_to_n(10), int)

def test_sum_to_n_with_boolean_true():
    assert sum_to_n(True) == 1

def test_sum_to_n_with_boolean_false():
    assert sum_to_n(False) == 0

def test_sum_to_n_with_string_raises_type_error():
    with pytest.raises(TypeError):
        sum_to_n("10")

def test_sum_to_n_with_float_raises_type_error():
    with pytest.raises(TypeError):
        sum_to_n(10.5)

def test_sum_to_n_with_none_raises_type_error():
    with pytest.raises(TypeError):
        sum_to_n(None)

def test_sum_to_n_with_list_raises_type_error():
    with pytest.raises(TypeError):
        sum_to_n([1, 2, 3])

def test_sum_to_n_idempotent_calls():
    assert sum_to_n(5) == sum_to_n(5)

def test_sum_to_n_with_large_positive_number_formula():
    n = 50000
    expected = n * (n + 1) // 2
    assert sum_to_n(n) == expected
